  'security-tips-heading' => 'सुरक्षा संबंधी विचार और संपीड़न युक्तियाँ',
  'security-tips-intro' => 'निम्नलिखित युक्तियाँ सुचारू और सुरक्षित संपीड़न सुनिश्चित करेंगी।',
  'tip1-heading' => 'फ़ाइल संपीड़न सुरक्षा',
  'tip1-para' => 'ऑनलाइन पीडीएफ संपीड़न के लिए इस बात पर ध्यान देने की आवश्यकता है कि उपकरण अपलोड किए गए दस्तावेज़ों को सुरक्षित रूप से कैसे संभालते हैं। विश्वसनीय प्लेटफ़ॉर्म संरक्षित कनेक्शन और नियंत्रित सर्वर वातावरण के माध्यम से फ़ाइलों को संसाधित करते हैं। उपयोगकर्ताओं को ऐसी सेवाएँ चुननी चाहिए जो संपीड़न प्रबंधन और दस्तावेज़ सुरक्षा को स्पष्ट रूप से समझाती हों।',
  'tip2-heading' => 'अपलोड की गई फ़ाइलों का स्वत: विलोपन',
  'tip2-para' => 'स्वतः विलोपन कम अवधारण अवधि के बाद सर्वर से संपीड़ित फ़ाइलों को हटा देता है। यह सुविधा जोखिम जोखिमों को कम करती है और संग्रहीत दस्तावेज़ों तक अनधिकृत पहुंच को सीमित करती है। स्पष्ट विलोपन समयसीमा उपयोगकर्ताओं को ऑनलाइन संपीड़न प्लेटफ़ॉर्म पर आत्मविश्वास से भरोसा करने में मदद करती है।',
  'tip3-heading' => 'सही संपीड़न स्तर चुनें',
  'tip3-para' => 'संतुलित संपीड़न फ़ाइल आकार को प्रभावी ढंग से कम करते हुए पठनीयता को बरकरार रखता है। मध्यम संपीड़न स्कैन की गई रिपोर्ट या ब्रोशर जैसे छवि-भारी दस्तावेज़ों के लिए उपयुक्त है। सावधानीपूर्वक चयन बार-बार साझा करने के दौरान अनावश्यक गुणवत्ता हानि को रोकता है।',
  'tip4-heading' => 'संपीड़न से पहले फ़ाइलें तैयार करें',
  'tip4-para' => 'अप्रयुक्त पृष्ठों को हटाने से अंतिम फ़ाइल का आकार काफी कम हो जाता है। ऑनलाइन टूल पर अपलोड करने से पहले उच्च-रिज़ॉल्यूशन वाली छवियों का आकार बदलने से लाभ होता है। स्वच्छ दस्तावेज़ अधिक कुशलता से संपीड़ित होते हैं और लगातार परिणाम देते हैं।',
  'tip5-heading' => 'एकाधिक संपीड़न चक्रों से बचें',
  'tip5-para' => 'बार-बार संपीड़न से पाठ की तीक्ष्णता और छवि स्पष्टता धीरे-धीरे कम हो जाती है। उपयोगकर्ताओं को किसी भी ऑनलाइन प्रसंस्करण से पहले मूल फ़ाइलों को सुरक्षित रूप से संग्रहीत रखना चाहिए। एकल-चरण संपीड़न गुणवत्ता बनाए रखता है और विश्वसनीय दस्तावेज़ आउटपुट सुनिश्चित करता है।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-para1' => 'पीडीएफ संपीड़न फ़ाइल का आकार कम करता है और सभी डिवाइसों में साझाकरण और भंडारण की गति में सुधार करता है। ऑनलाइन पीडीएफ संपीड़न उपकरण उपयोगकर्ताओं को आकर्षित करते हैं क्योंकि ब्राउज़र टूल को किसी सॉफ़्टवेयर इंस्टॉलेशन की आवश्यकता नहीं होती है। लोकप्रिय सेवाएँ तेज़ परिणाम, सरल इंटरफ़ेस प्रदान करती हैं और कई प्लेटफ़ॉर्म का समर्थन करती हैं।',
  'conclusion-para2' => 'संपीड़न उपकरण प्रसंस्करण के दौरान दस्तावेजों, छवियों, फ़ॉन्ट और अप्रयुक्त तत्वों का विश्लेषण करते हैं। छवि अनुकूलन और स्मार्ट क्लीनअप समग्र आकार को कम करते हुए गुणवत्ता बनाए रखने में मदद करते हैं। विश्वसनीय प्लेटफ़ॉर्म एन्क्रिप्शन और स्पष्ट ऑटो-डिलीशन नीतियों के साथ फ़ाइलों की सुरक्षा करते हैं।',
  'conclusion-para3' => 'उपयोगकर्ता फ़ाइलें डाउनलोड करने से पहले उपयुक्त संपीड़न स्तर का चयन करके बेहतर परिणाम प्राप्त करते हैं। जब उपयोगकर्ता अप्रयुक्त पृष्ठों, छवियों और फ़ॉन्ट को हटाते हैं तो तैयार किए गए दस्तावेज़ कुशलतापूर्वक संपीड़ित होते हैं। एकल-चरण संपीड़न स्पष्टता बनाए रखता है और कार्य वातावरण में विश्वसनीय साझाकरण सुनिश्चित करता है।',
  'faqs-heading' => 'पूछे जाने वाले प्रश्न',
  'faq1-question' => 'क्या ऑनलाइन कम्प्रेशन सुरक्षित है?',
  'faq1-answer' => 'जब उपयोगकर्ता स्पष्ट सुरक्षा नीतियों के साथ प्रतिष्ठित प्लेटफ़ॉर्म चुनते हैं तो ऑनलाइन संपीड़न सुरक्षित रहता है। विश्वसनीय उपकरण फ़ाइल प्रसंस्करण के दौरान सुरक्षित कनेक्शन और नियंत्रित सर्वर का उपयोग करते हैं। संवेदनशील दस्तावेज़ों को संभालते समय उपयोगकर्ताओं को अज्ञात वेबसाइटों से बचना चाहिए।',
  'faq2-question' => 'आकार में कितनी कमी संभव है?',
  'faq2-answer' => 'आकार में कमी दस्तावेज़ की सामग्री, जैसे छवियाँ, फ़ॉन्ट और पृष्ठ संरचना पर निर्भर करती है। टेक्स्ट-भारी पीडीएफ आमतौर पर छवि-समृद्ध फ़ाइलों की तुलना में उच्च संपीड़न दर प्राप्त करते हैं। अधिकांश उपकरण फ़ाइल का आकार 20% से 70% के बीच कम कर देते हैं।',
  'faq3-question' => 'क्या पीडीएफ संपीड़न मुफ़्त है?',
  'faq3-answer' => 'कई ऑनलाइन पीडीएफ संपीड़न समाधान बुनियादी सुविधाओं और सीमाओं के साथ मुफ्त उपयोग की पेशकश करते हैं। मुफ़्त संस्करण अक्सर दैनिक अपलोड या उपलब्ध संपीड़न शक्ति को प्रतिबंधित करते हैं। सशुल्क योजनाएँ उच्च सीमाएँ, तेज़ प्रसंस्करण और उन्नत नियंत्रण अनलॉक करती हैं।',
  'faq4-question' => 'क्या पीडीएफ संपीड़न गुणवत्ता को प्रभावित करता है?',
  'faq4-answer' => 'चयनित सेटिंग्स और दस्तावेज़ प्रकार के आधार पर संपीड़न गुणवत्ता को प्रभावित कर सकता है। मध्यम संपीड़न आमतौर पर पठनीयता और लेआउट सटीकता को बरकरार रखता है। उच्च संपीड़न छवि की तीक्ष्णता को कम कर सकता है, लेकिन पाठ को स्पष्ट रखता है।',
  'faq5-question' => 'क्या पीडीएफ संपीड़न के बाद फ़ाइलें स्वचालित रूप से हटा दी जाती हैं?',
  'faq5-answer' => 'कई ऑनलाइन टूल छोटी अवधारण अवधि के बाद अपलोड की गई फ़ाइलों को स्वचालित रूप से हटा देते हैं। स्वतः विलोपन डेटा एक्सपोज़र को कम करता है और उपयोगकर्ता की गोपनीयता सुरक्षा में सुधार करता है। उपयोगकर्ताओं को प्रत्येक प्लेटफ़ॉर्म नीति अनुभाग में विलोपन समयसीमा की पुष्टि करनी चाहिए।',
);
